INSERT INTO `pelamar_profiles` (`id`, `user_id`, `nama_lengkap`, `no_telepon`, `alamat`, `ringkasan_diri`, `linkedin_url`, `portfolio_url`, `created_at`, `updated_at`, `judul_posisi`, `keahlian`, `sertifikasi`, `pengalaman_kerja`, `riwayat_pendidikan`, `social_links`) VALUES ('b0708e8f-0c53-4538-8b69-4c1fab8c54e3', 'b7dca700-37b7-4704-bcd8-e7b19a8b2fcc', 'Aji', '111111111', 'Jakarta, Indonesia', 'Senior Frontend Engineer berpengalaman 4+ tahun dalam merancang antarmuka web performan tinggi menggunakan Next.js, React, TypeScript, dan Tailwind CSS. Terbiasa mengoptimalkan Web Vitals dan berkolaborasi dalam tim agile.', 'linkedin.com/in/pelamar', NULL, '2026-08-03 06:20:34', '2026-08-03 07:19:03', NULL, NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
