INSERT INTO `job_postings` (`id`, `perusahaan_id`, `kategori_id`, `judul_posisi`, `deskripsi_pekerjaan`, `kualifikasi`, `tanggung_jawab`, `tipe_pekerjaan`, `lokasi_kerja`, `kota`, `gaji_min`, `gaji_max`, `tampilkan_gaji`, `pengalaman_min_tahun`, `pendidikan_min`, `cv_threshold`, `interview_threshold`, `status`, `tanggal_buka`, `tanggal_tutup`, `created_at`, `updated_at`, `jd_embedding`, `department`, `experience_level`, `benefits_json`, `ai_keywords_json`, `video_questions_json`, `openings_count`) VALUES ('74524aaf-76b1-459b-850a-af44d38a5e3b', '9762b653-5521-4543-a0d0-633828c0a094', '28d0b388-3cc0-489c-8530-a2140522a79e', 'Front End Developer', 'Kami adalah startup teknologi yang sedang membangun platform Saas e-commerce.
Saat ini kami mencari Front end Developer yang memiliki pengalaman menggunakan website builder editor, khususnya dalam membangun theme, mendesain tampilan website, serta melakukan kustomisasi agar menghasilkan website yang responsif, menarik, dan mudah digunakan.', '["Pengalaman minimal 1 - 3 tahun sebagai Front end Developer atau Website Developer.","Memiliki pengalaman membangun serta kustomisasitheme menggunakan builder editor.","Memiliki pengalaman menggunakan framework Next Js.","Memiliki kemampuan problem solving yang baik.","Mampu bekerja secara mandiri maupun  dalam tim.","Terbiasa menggunakan GitHub atau Gitlab.","Terbiasa menerapkan prinsip Clean Code dalam proses pengembangan."]', '["Membangun dan mengembangkan tampilan website menggunakan website builder editor.","Melakukan kustomisasi theme dan layout sesuai kebutuhan desain.","Mengimplementasikan desain UI/UX menjadi website yang responsif dan user friendly.","Melakukan pengembangan builder editor.","Menyesuaikan tampilan website untuk berbagai perangkat (dekstop, tablet, dan mobile).","Melakukan maintenance, bug fixing, dan improvement terhadap builder editor.","Berkolaborasi dengan tim UI/UX, Back-end, System Analyst, dan QA dalam proses penggunaan builder."]', 'Full-time', 'onsite', 'Jakarta', '4000000.00', '5000000.00', 1, 0, 'S2', '60.00', '60.00', 'active', '2026-09-03 00:00:00', '2026-08-12 00:00:00', '2026-08-11 07:43:51', '2026-09-12 06:54:36', '[-0.04552669823169708, -0.10579194873571396, -0.02471795305609703, 0.022548463195562363, -0.018947314471006393, 0.02815609984099865, -0.07541266828775406, -0.020676681771874428, -0.028683943673968315, 0.08741716295480728, -0.05801146849989891, 0.0499635711312294, 0.03318323567509651, -0.015984583646059036, 0.035551365464925766, 0.05154211446642876, -0.021523620933294296, -0.009910757653415203, 0.059368032962083817, -0.06438902765512466, -0.03896956890821457, -0.04478362202644348, 0.08722490072250366, -0.07352852821350098, -0.032991793006658554, -0.0215