INSERT INTO `job_postings` (`id`, `perusahaan_id`, `kategori_id`, `judul_posisi`, `deskripsi_pekerjaan`, `kualifikasi`, `tanggung_jawab`, `tipe_pekerjaan`, `lokasi_kerja`, `kota`, `gaji_min`, `gaji_max`, `tampilkan_gaji`, `pengalaman_min_tahun`, `pendidikan_min`, `cv_threshold`, `interview_threshold`, `status`, `tanggal_buka`, `tanggal_tutup`, `created_at`, `updated_at`, `jd_embedding`, `department`, `experience_level`, `benefits_json`, `ai_keywords_json`, `video_questions_json`, `openings_count`) VALUES ('380b857b-b753-4162-9309-a42ca6d89031', '9762b653-5521-4543-a0d0-633828c0a094', '2bbbd1b8-f230-4e5c-8f4a-a27eeb8c2c91', 'project manager', 'Kami mencari seorang Project Manager berpengalaman dan berdedikasi untuk bergabung dengan tim kami di PT Mitra Sinergi Konstruksi. Sebagai Project Manager, Anda akan memainkan peran strategis dalam merencanakan, mengkoordinasikan, dan mengawasi proyek-proyek konstruksi dari tahap awal hingga penyelesaian. Anda akan bertanggung jawab untuk memastikan proyek diselesaikan tepat waktu, sesuai anggaran, dan memenuhi standar kualitas tertinggi. Posisi ini merupakan pekerjaan tetap penuh waktu yang berlokasi di South Tangerang, Banten, memungkinkan Anda untuk bekerja langsung di lapangan dan kantor pusat kami.', '["Gelar Sarjana dalam Teknik Sipil.","Minimal 5 tahun pengalaman sebagai Project Manager dalam industri konstruksi."]', '["Merencanakan dan mengembangkan strategi proyek konstruksi, termasuk penjadwalan, penetapan anggaran, dan alokasi sumber daya.","Memimpin dan mengkoordinasikan tim proyek, termasuk kontraktor, subkontraktor, dan tenaga kerja lapangan untuk memastikan pelaksanaan yang efisien.","Memantau kemajuan proyek secara berkala dan membuat laporan status kepada manajemen senior dan klien."]', 'Contract', 'onsite', 'bali, indonesia', '10000000.00', '15000000.00', 0, 0, 'SMA/SMK', '60.00', '60.00', 'active', '2026-09-12 00:00:00', '2026-09-24 00:00:00', '2026-09-12 06:26:38', '2026-09-12 06:26:38', '[0.0172670222818851