INSERT INTO `job_postings` (`id`, `perusahaan_id`, `kategori_id`, `judul_posisi`, `deskripsi_pekerjaan`, `kualifikasi`, `tanggung_jawab`, `tipe_pekerjaan`, `lokasi_kerja`, `kota`, `gaji_min`, `gaji_max`, `tampilkan_gaji`, `pengalaman_min_tahun`, `pendidikan_min`, `cv_threshold`, `interview_threshold`, `status`, `tanggal_buka`, `tanggal_tutup`, `created_at`, `updated_at`, `jd_embedding`, `department`, `experience_level`, `benefits_json`, `ai_keywords_json`, `video_questions_json`, `openings_count`) VALUES ('d8b05120-b4d3-4106-8fe9-4b2d56b9fd4c', '9762b653-5521-4543-a0d0-633828c0a094', '28d0b388-3cc0-489c-8530-a2140522a79e', 'Fullstack Developer', 'Kami mencari Full Stack Developer yang berpengalaman untuk merancang, mengembangkan, menguji, dan memelihara aplikasi web end-to-end. Kandidat akan bertanggung jawab mengembangkan sisi Front-End dan Back-End, memastikan aplikasi memiliki performa tinggi, aman, scalable, dan mudah dipelihara. Posisi ini akan berkolaborasi erat dengan Product Manager, UI/UX Designer, QA Engineer, dan tim Engineering lainnya untuk menghasilkan solusi digital yang berkualitas.', '["Strong proficiency in JavaScript and/or TypeScript.","Experience with at least one Front-End framework such as:  React.js  Next.js  Angular  Vue.js","Experience with Back-End technologies such as:  Node.js (Express/NestJS)  Java (Spring Boot)  .NET Core  Python (Django/FastAPI)  Experience building and consuming REST APIs.  Strong understanding of HTML5, CSS3, Responsive Design, and modern UI development.","Experience with relational databases (MySQL, PostgreSQL, SQL Server) and/or NoSQL databases (MongoDB, Redis).","Familiarity with Git version control.","Understanding of authentication methods such as JWT and OAuth.","Experience working with Agile methodology.","Experience with cloud platforms (AWS, Azure, or Google Cloud).","Experience implementing CI/CD pipelines.","Knowledge of Microservices Architecture."]', '["Min. 5 years as Fullstack: reacr & java springboot.","Excellent skills in microservice and microfrontend","Redis, active/kafka/rabbit MySQL and PostgreSQL","Develop, maintain, and enhance responsive web applications from front-end to back-end.","Build reusable, scalable, and maintainable code following software engineering best practices.","Design and develop RESTful APIs and integrate third-party services.","Develop responsive and user-friendly interfaces based on UI/UX designs.","Optimize application performance, scalability, and security.","Design, implement, and maintain relational or NoSQL databases.","Troubleshoot, debug, and resolve production issues.","Write unit tests and participate in code reviews."]', 'Full-time', 'onsite', 'Jakarta', '6000000.00', '8000000.00', 1, 0, 'SMA/SMK', '60.00', '60.00', 'active', '2026-09-12 00:00:00', '2026-09-13 00:00:00', '2026-08-12 06:43:40', '2026-09-12 18:54:35', '[-0.04666208475828171, -0.03420983627438545, -0.03236762061715126, -0.0377766489982605, -0.050450846552848816, 0.011299658566713333, -0.10039854794740677, 0.017749061807990074, -0.05224922299385071, 0.04668610170483589, -0.09554831683635712, 0.00025522802025079727, 0.04460827633738518, -0.028366507962346077, 0.010478638112545013, 0.044217173010110855, 0.002513111801818013, 0.008602139540016651, 0.06115772947669029, -0.026202330365777016, -0.05414128303527832, -0.053586266934871674, 0.07498878240585327, -0.07475452870130539, -0.07663577049970627, 0.013021892867982388, 0.023351671174168587, -0.0018777434015646577, 0.01686442643404007, -0.10612166672945023, 0.057986803352832794, -0.012968407943844795, 0.010325482115149498, 0.008039087057113647, -0.09038473665714264, 0.10201429575681686, -0.03200950846076012, -0.0062573920004069805, -0.02623337134718895, -0.018808402121067047, -0.0351143516600132, 0.06516420096158981, -0.02209428697824478, -0.01956864260137081, -0.03161509707570076, -0.09323164075613022, -0.06205332279205322, -0.05748477578163147, -0.0850968286395073, 0.013222062028944492, -0.01693342626094818, -0