INSERT INTO `cv_documents` (`id`, `pelamar_id`, `nama_file`, `file_url`, `file_type`, `file_size_kb`, `extracted_text`, `cleaned_text`, `embedding_vector`, `uploaded_at`, `email`, `phone`, `pendidikan_tertinggi`, `is_ocr_used`) VALUES ('a52127e5-69f8-446d-b811-814b2893434d', '57f1577a-e188-408e-bd95-f9294e959e68', 'Profil_CV_Dashboard.json', 'profil-dashboard', 'json', 1, 'Nama: Nur Aji Purnomo
Posisi/Jabatan: Mahasiswa Teknik Informatika / Software & Android Developer
Deskripsi Diri: Mahasiswa Sarjana Terapan Teknik Informatika di Universitas Harkat Negeri dengan minat kuat dan pengalaman praktis dalam pengembangan perangkat lunak, aplikasi mobile (Android), dan Kecerdasan Buatan (AI). Terbiasa berkolaborasi dalam tim pengembangan menggunakan Jira dan GitHub (Bumi Tekno Indonesia), serta merancang arsitektur aplikasi menggunakan MongoDB Atlas dan Supabase. Memiliki pengalaman dalam merancang aplikasi edukasi berbasis AI (EDUTECH) dan integrasi Augmented Reality (Vuforia Engine). Aktif dalam komunitas IT (PLUG-IN) dan berkontribusi pada penulisan akademik (Journal of Applied Community Service).
Keahlian (Skills): [{"category":"Pengembangan Perangkat Lunak & Database","items":"Android Development, Web Deployment (InfinityFree)"},{"category":"Kecerdasan Buatan (AI) & Augmented Reality (AR)","items":"Hugging Face (Akses ke model AI berlisensi/gated)"},{"category":"Keamanan Siber (Cybersecurity) & Infrastruktur","items":"picoCTF (Penyelesaian tantangan keamanan siber)"}]
Pengalaman Kerja:
[{"company":"PT Bumi Tekno","role":"Tim Pengembang (GitHub Contributor) | Bumi Tekno Indonesia","period":"2024-2027","description":"Berkolaborasi dalam repositori pengembangan perangkat lunak tim Bumi Tekno Indonesia di GitHub."}]
