INSERT INTO `cv_documents` (`id`, `pelamar_id`, `nama_file`, `file_url`, `file_type`, `file_size_kb`, `extracted_text`, `cleaned_text`, `embedding_vector`, `uploaded_at`, `email`, `phone`, `pendidikan_tertinggi`, `is_ocr_used`) VALUES ('1aa53b2a-6bed-4695-aab3-b9a780e3a3a1', '57f1577a-e188-408e-bd95-f9294e959e68', 'Profil_CV_Dashboard.json', 'profil-dashboard', 'json', 1, 'Nama: Nur Aji Purnomo
Posisi/Jabatan: Front End Developer / Website Developer
Deskripsi Diri: Profesional IT dan Mahasiswa Sarjana Terapan Teknik Informatika di Universitas Harkat Negeri dengan pengalaman praktis dalam pengembangan perangkat lunak dan pembuatan website yang responsif. Memiliki kemampuan kuat dalam mengimplementasikan desain UI/UX menjadi antarmuka yang user-friendly, serta terbiasa menerapkan prinsip Clean Code. Berpengalaman menggunakan platform version control seperti GitHub dan alat manajemen proyek seperti Jira untuk berkolaborasi dengan tim lintas divisi (Bumi Tekno Indonesia). Mampu beradaptasi dengan teknologi front-end modern (termasuk eksplorasi framework seperti Next.js dan website builder) untuk memberikan solusi website yang menarik dan fungsional.
Keahlian (Skills): [{"category":"Pengembangan Perangkat Lunak & Database","items":"Android Development, Web Deployment (InfinityFree)"},{"category":"Kecerdasan Buatan (AI) & Augmented Reality (AR)","items":"Hugging Face (Akses ke model AI berlisensi/gated)"},{"category":"Keamanan Siber (Cybersecurity) & Infrastruktur","items":"picoCTF (Penyelesaian tantangan keamanan siber)"}]
Pengalaman Kerja:
[{"company":"PT Bumi Tekno","role":"Web Developer & Administrator","period":"2024-2027","description":"Melakukan kustomisasi tampilan, layout, dan pemeliharaan website agar responsif dan mudah digunakan di berbagai perangkat (desktop dan mobile)."}]
