INSERT INTO `cv_documents` (`id`, `pelamar_id`, `nama_file`, `file_url`, `file_type`, `file_size_kb`, `extracted_text`, `cleaned_text`, `embedding_vector`, `uploaded_at`, `email`, `phone`, `pendidikan_tertinggi`, `is_ocr_used`) VALUES ('69913799-f15f-4ce0-86be-4993e8f3aa17', 'd611b6b4-bfbe-44b8-9eb1-6a7dd3d02b1d', 'Profil_CV_Dashboard.json', 'profil-dashboard', 'json', 2, 'Nama: Arya Fahrezi Amarully
Posisi/Jabatan: Fullstack Developer
Deskripsi Diri: Mahasiswa S1 Ilmu Komputer yang detail dan fokus, khususnya di Pengembangan Web Full-Stack. Terampil dalam membangun antarmuka pengguna yang responsif dan sistem back-end yang kuat menggunakan framework modern seperti Laravel dan React. Mahir dalam manajemen database dan integrasi API melalui proyek akademik langsung. Semangat untuk membawa kemampuan pemecahan masalah yang kuat ke program magang di tempat kerja, di mana saya bisa berkolaborasi dengan tim pengembangan profesional.
Keahlian (Skills): [{"category":"Programming Languages","items":" Dart, PHP (Native/Laravel), JavaScript, HTML, CSS."},{"category":"Frameworks & Libraries","items":"Flask, Flutter, Laravel, Bootstrap"},{"category":"Databases & Tools","items":" Supabase, MySQL, Git, Postman, Notion, Hugging Face."},{"category":"Design & Methodologies","items":" UI/UX Design, MVC Architecture, Kaizen / Lean Process."},{"category":"Other","items":" Public Speaking, Problem-Solving, Teamwork, Collaborations, Project Coordination"}]
Pengalaman Kerja:
[{"company":"PT Astra Daihatsu","role":"Team Member","period":"2021 - 2023","description":"Bekerja sama dalam tim lintas fungsi untuk mencapai target produksi harian dengan volume tinggi di bawah standar manufaktur dan kualitas yang ketat. Menerapkan prinsip Kaizen (perbaikan terus-menerus) untuk mengidentifikasi kendala alur kerja dan mengoptimalkan efisiensi proses di lini produksi. Mengoperasikan sistem kontrol otomatis dan memantau data produksi untuk memastikan pelaksanaan yang tepat dan kontrol kualitas tanpa cacat."},{"company":"PT Bumi Tekno","role":"Magang","period":"2026 - sekarang","description":"Mengembangkan aplikasi web responsif menggunakan Laravel (arsitektur MVC) dan Bootstrap, memungkinkan digitalisasi operasional dari sistem pemesanan manual ke platform otomatis. Merancang dan mengelola skema database MySQL yang efisien untuk menangani inventaris produk, kategori menu, dan data pesanan secara sistematis. Mengimplementasikan JavaScript untuk fitur interaktif dan validasi sisi klien pada formulir pesanan guna meningkatkan pengalaman pengguna dan antarmuka (UI/UX) secara keseluruhan."}]
Pendidikan:
[{"school":"Universitas Harkat Negeri","degree":"D4 Teknik Informatika","period":"2023 - sekarang","gpa":"3.78"}]', 'Nama: Arya Fahrezi Amarully
