INSERT INTO `applications` (`id`, `pelamar_id`, `job_id`, `cv_document_id`, `status`, `catatan_pelamar`, `applied_at`, `updated_at`, `ai_result`, `video_url`, `catatan_perusahaan`, `interview_details`) VALUES ('3e13dd11-f0af-4ff8-9877-291de04806dc', 'd611b6b4-bfbe-44b8-9eb1-6a7dd3d02b1d', 'd8b05120-b4d3-4106-8fe9-4b2d56b9fd4c', '69913799-f15f-4ce0-86be-4993e8f3aa17', 'human_validation', '', '2026-09-14 13:40:49', '2026-09-14 13:44:03', '{"status": "SUKSES", "pelafalan": {"status": "Pelafalan Tidak Jelas", "keterangan": "Pelafalan kandidat tidak jelas atau artikulasi suara kurang dapat diidentifikasi secara optimal oleh sistem pengenalan suara.", "avg_logprob": -0.83, "kejelasan_artikulasi": "Kurang Jelas"}, "durasi_teks": "0 Menit 59 Detik", "kategori_fit": "Cukup", "kualitas_teks": "Audio & Video Clear (720p)", "full_transcript": "Selamat datang. Selamat datang. Perganakan saya, Ria Faria yang maruli saya melusand dari Universitas Rakan Kri program. Sersiannya terapan, tak di informatika. Saya dengan posisi Full Stuck developer. Saya sudah menyalas saya akan beberapa projek. Sudah ada kurang lebih lemap projek yang sudah saya selesaikan. Diandari yang dua tadi ke web set dan dua apps Mobile. Saya muduskan untuk melamar atau mengapalai lo langgan ini. Karena saya lihat Job Des, dan download Job Des dan juga pershare. Ternyata itu sudah cocok dengan saya. Dan saya akan cifis saya pengalaman saya dan semua kalian saya itu. Cau cocok dengan pokas ini. Sekian, mazahan mereka mau remat-mat-mat.", "durasi_formatted": "00:59", "skor_keseluruhan": 62.0, "total_pertanyaan": 3, "ringkasan_jawaban": "Kandidat telah menyelesaikan sesi wawancara video dan menjawab seluruh 3 pertanyaan yang diajukan secara terstruktur.\\n\\n• ceritakan siapa kamu ?: Kandidat memperkenalkan diri (lulusan/mahasiswa dari Universitas Rakan Kri, bidang studi Teknik Informatika/Komputer, dengan fokus keahlian sebagai Full Stuck developer). (Catatan: Pelafalan suara kurang jelas).\\n• Berapa Projek yang sudah Kamu buat ? sebutkan: Kandidat memaparkan pengalaman proyeknya, di mana kandidat telah menyelesaikan beberapa proyek, yang mencakup pengembangan aplikasi website dan aplikasi mobile. (Catatan: Pelafalan suara kurang jelas).\\n• Mengapa kamu memutuskan untuk melamar di posisi ini ?: Kandidat menyatakan motivasi melamar didasari oleh deskripsi pekerjaan (job desk) serta persyaratan yang sesuai, keselarasan kualifikasi dan keahlian yang dimiliki. (Catatan: Pelafalan suara kurang jelas).\\n\\n⚠️ Catatan Artikulasi: Pelafalan kandidat terdeteksi tidak jelas atau suara kurang terdengar jernih saat menjawab pertanyaan.\\n\\nDisarankan untuk melakukan peninjauan lebih lanjut pada aspek pertanyaan yang belum terjawab atau pelafalan yang kurang jelas saat tahapan seleksi lanjutan.", "dimensi_psikologis": {"Ability": "50.0%", "Attitude": "79.0%", "Intelligent": "82.7%", "Personality": "70.8%", "Emotional Intelligent": "93.5%"}, "durasi_video_detik": 59.7, "parameter_analisis": {"kontak_mata": 36.7, "gerakan_badan": 50.0, "gerakan_kepala": 60.0, "gerakan_tangan": 86.7, "word_per_second": 1.76, "kejelasan_pelafalan": "Pelafalan Tidak Jelas", "word_per_second_percent": 70.4}, "analisis_pertanyaan": [{"nomor": 1, "status": "Terjawab", "kutipan": "Selamat datang. Selamat datang. Perganakan saya, Ria Faria yang maruli saya melusand dari Universitas Rakan Kri program. Sersiannya terapan, tak di informatika. Saya dengan posisi Full Stuck developer.", "pelafalan": "Pelafalan Tidak Jelas", "ringkasan": "Kandidat memperkenalkan diri (lulusan/mahasiswa dari Universitas Rakan Kri, bidang studi Teknik Informatika/Komputer, dengan fokus keahlian sebagai Full Stuck developer). (Catatan: Pelafalan suara kurang jelas).", "pertanyaan": "ceritakan siapa kamu ?", "waktu_mulai": 0.0, "waktu_selesai": 21.0, "skor_relevansi": 75, "pelafalan_jelas": false, "catatan_pelafalan": "Pelafalan tidak jelas"}, {"nomor": 2, "status": "Terjawab", "kutipan": "Saya sudah menyalas saya akan beberapa projek. Sudah ada kurang lebih lemap projek yang sudah saya selesaikan. Diandari yang dua tadi ke web set dan dua apps Mobile.", "pelafalan": "Pelafalan Tidak Jelas", "ringkasan": "Kandidat memaparkan pengalaman proyeknya, di mana kandidat telah menyelesaikan beberapa proyek, yang mencakup pengembangan aplikasi website dan aplikasi mobile. (Catatan: Pelafalan suara kurang jelas).", "pertanyaan": "Berapa Projek yang sudah Kamu buat ? sebutkan", "waktu_mulai": 21.0, "waktu_selesai": 33.0, "skor_relevansi": 98, "pelafalan_jelas": false, "catatan_pelafalan": "Pelafalan tidak jelas"}, {"nomor": 3, "status": "Terjawab", "kutipan": "Saya muduskan untuk melamar atau mengapalai lo langgan ini. Karena saya lihat Job Des, dan download Job Des dan juga pershare. Ternyata itu sudah cocok dengan saya. Dan saya akan cifis saya pengalaman saya dan semua kalian saya itu. Cau cocok dengan pokas ini. Sekian, mazahan mereka mau remat-mat-mat.", "pelafalan": "Pelafalan Tidak Jelas", "ringkasan": "Kandidat menyatakan motivasi melamar didasari oleh deskripsi pekerjaan (job desk) serta persyaratan yang sesuai, keselarasan kualifikasi dan keahlian yang dimiliki. (Catatan: Pelafalan suara kurang jelas).", "pertanyaan": "Mengapa kamu memutuskan untuk melamar di posisi ini ?", "waktu_mulai": 33.0, "waktu_selesai": 59.0, "skor_relevansi": 75, "pelafalan_jelas": false, "catatan_pelafalan": "Pelafalan tidak jelas"}], "status_jawaban_teks": "3 dari 3 Pertanyaan Terjawab", "pertanyaan_terjawab_count": 3}', 'https://pub-b7ce15fda46746cfa3438807f5592cf5.r2.dev/interviews/c3aaefcb23be_WhatsApp_Video_2026-09-04_at_23.47.44.mp4', NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
