INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_otp_subject', '"Kode OTP Verifikasi - AI Recruit Pro"', '2026-09-05 18:23:21') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_otp_body', '"Halo {nama_penerima},\\n\\nKode OTP verifikasi akun Anda adalah:\\n\\n{otp_code}\\n\\nKode ini berlaku selama {kadaluarsa_menit} menit. Harap jangan memberikan kode ini kepada siapapun demi keamanan akun Anda.\\n\\nSalam hormat,\\nTim AI Recruit Pro"', '2026-09-05 18:23:21') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_company_approved_subject', '"Selamat! Pengajuan Akun Perusahaan {nama_perusahaan} Telah Terverifik"', '2026-09-05 18:23:21') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_company_approved_body', '"Halo Tim {nama_perusahaan},\\n\\nKabar baik! Dokumen legalitas dan data profil perusahaan Anda telah diverifikasi dan disetujui oleh tim kurator AI Recruit Pro.\\n\\nAkun perusahaan Anda kini berstatus Resmi & Terverifikasi (Verified). Anda sudah dapat membuat lowongan kerja baru, mengelola pelamar, dan memanfaatkan fitur AI ATS.\\n\\nSilakan login ke portal dashboard perusahaan Anda:\\n{login_url}\\n\\nTerima kasih telah mempercayakan kebutuhan rekrutmen Anda kepada AI Recruit Pro!\\n\\nSalam sukses,\\nTim AI Recruit Pro"', '2026-09-05 18:23:21') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_company_rejected_subject', '"Pemberitahuan Status Verifikasi Akun Perusahaan {nama_perusahaan}"', '2026-09-05 18:23:21') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_company_rejected_body', '"Halo Tim {nama_perusahaan},\\n\\nTerima kasih telah mendaftar dan mengajukan verifikasi profil perusahaan di platform AI Recruit Pro.\\n\\nSetelah dilakukan peninjauan dokumen, saat ini pengajuan verifikasi perusahaan Anda belum dapat kami setujui dengan catatan penolakan berikut:\\n\\"{alasan_penolakan}\\"\\n\\nAnda dapat memperbarui data atau mengunggah ulang dokumen legalitas yang sesuai dengan masuk kembali ke akun Anda melalui tautan berikut:\\n{revisi_url}\\n\\nJika ada kendala atau pertanyaan lebih lanjut, silakan hubungi tim dukungan kami.\\n\\nSalam hormat,\\nTim Verifikasi AI Recruit Pro"', '2026-09-05 18:23:21') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('smtp_pass', '"xrho qlix wqqa aamu"', '2026-09-11 02:35:56') ON DUPLICATE KEY UPDATE id=id;
