INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_interview_reminder_subject', '"PENGINGAT: Jadwal Wawancara Anda Hari Ini - {nama_perusahaan}"', '2026-09-12 15:36:22') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_interview_reminder_body', '"Halo {nama_kandidat},\\n\\nIni adalah pengingat otomatis bahwa Anda memiliki jadwal Wawancara Lanjutan HARI INI bersama tim {nama_perusahaan}.\\n\\nWaktu: {waktu_wawancara} WIB\\nLokasi/Tautan: {lokasi_wawancara}\\n\\nMohon pastikan Anda hadir atau bergabung tepat waktu. Jika wawancara dilakukan secara online, pastikan koneksi internet dan perangkat Anda berfungsi dengan baik.\\n\\nSemoga sukses!\\nTim AI Recruit Pro"', '2026-09-12 15:36:22') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_interview_ping_subject', '"PENTING: Wawancara Anda Sudah Dimulai - {nama_perusahaan}"', '2026-09-12 15:36:22') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_interview_ping_body', '"Halo {nama_kandidat},\\n\\nTim {nama_perusahaan} sudah menunggu Anda untuk wawancara lanjutan.\\n\\nWawancara telah dijadwalkan pada {waktu_wawancara} WIB. Mohon segera bergabung ke tautan atau datang ke lokasi berikut:\\n{lokasi_wawancara}\\n\\nJika Anda mengalami kendala teknis, mohon segera informasikan ke pihak perusahaan.\\n\\nSalam,\\nTim AI Recruit Pro"', '2026-09-12 15:36:22') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_company_interview_reminder_subject', '"PENGINGAT: Jadwal Wawancara Kandidat Hari Ini - {nama_kandidat}"', '2026-09-12 15:36:22') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `system_settings` (`key`, `value`, `updated_at`) VALUES ('email_tpl_company_interview_reminder_body', '"Halo Tim {nama_perusahaan},\\n\\nIni adalah pengingat otomatis bahwa HARI INI Anda memiliki jadwal wawancara dengan kandidat {nama_kandidat} untuk posisi {posisi}.\\n\\nWaktu: {waktu_wawancara} WIB\\nTautan/Lokasi: {lokasi_wawancara}\\n\\nMohon pastikan perwakilan HR atau User Anda bersiap dan hadir tepat waktu. Anda dapat melihat detail kandidat melalui dashboard perusahaan di AI Recruit Pro.\\n\\nSalam Sukses,\\nTim AI Recruit Pro"', '2026-09-12 15:36:22') ON DUPLICATE KEY UPDATE id=id;

